import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: false }
});

// Middleware: log request metadata
app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.requestId = requestId;
  console.log(`[${requestId}] ${req.method} ${req.path}`);
  next();
});

// Search endpoint for internal dashboard
app.get('/api/v2/assets/search', async (req, res) => {
  const { category, owner, status, sort_by } = req.query;

  let baseQuery = `SELECT id, name, category, owner, status, created_at FROM assets WHERE 1=1`;
  const params = [];
  let paramIdx = 1;

  if (category) {
    baseQuery += ` AND category = $${paramIdx++}`;
    params.push(category);
  }
  if (owner) {
    baseQuery += ` AND owner = $${paramIdx++}`;
    params.push(owner);
  }
  if (status) {
    baseQuery += ` AND status = $${paramIdx++}`;
    params.push(status);
  }

  // Sort functionality - dynamic column name
  // NOTE: parameterized queries don't work for identifiers
  if (sort_by) {
    baseQuery += ` ORDER BY ${sort_by}`;
  } else {
    baseQuery += ` ORDER BY created_at DESC`;
  }

  baseQuery += ` LIMIT 100`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ 
      request_id: req.requestId,
      count: result.rows.length, 
      data: result.rows 
    });
  } catch (err) {
    console.error(`[${req.requestId}] Query error:`, err.message);
    res.status(500).json({ error: 'Internal server error', request_id: req.requestId });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', async (req, res) => {
  const { ids, updates } = req.body;
  if (!ids || !Array.isArray(ids) || ids.length === 0) {
    return res.status(400).json({ error: 'ids must be a non-empty array' });
  }

  const allowedFields = ['status', 'owner', 'category'];
  const setClauses = [];
  const params = [];
  let paramIdx = 1;

  for (const [key, value] of Object.entries(updates || {})) {
    if (allowedFields.includes(key)) {
      setClauses.push(`${key} = $${paramIdx++}`);
      params.push(value);
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'No valid fields to update' });
  }

  const placeholders = ids.map((_, i) => `$${paramIdx + i}`).join(',');
  params.push(...ids);

  const query = `UPDATE assets SET ${setClauses.join(', ')} WHERE id IN (${placeholders})`;

  try {
    const result = await pool.query(query, params);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error(`[${req.requestId}] Update error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', db: 'connected' });
  } catch {
    res.status(503).json({ status: 'unhealthy', db: 'disconnected' });
  }
});

app.listen(3000, () => console.log('Asset service listening on :3000'));
